    bubble.style.fontSize = '0.92rem';
    bubble.style.color = 'var(--text-main)';
    bubble.style.lineHeight = '1.55';
    bubble.style.boxShadow = 'var(--shadow-sm)';

    const sender = document.createElement('div');
